// Dossier de sortie dans le dossier des sources : une sortie à nom fixe (le manifeste, `mjs-precache.json`, la feuille
// `<module>.<nom>.css` d'un `<style name="…">`) ne remplace un fichier qui existe déjà que s'il porte la marque des
// fichiers produits par la construction (première ligne `/* @generated by ModularJS */`, clé `"@generated"` du JSON) ou
// s'il est reconnu comme une sortie d'une version précédente (manifeste et `mjs-precache.json` de la 2.5.0). La preuve
// tenait dans le registre `.mjs-outputs.json` : registre absent (clone neuf, registre ignoré par git) ou manifeste rangé
// ailleurs, et la construction refusait ses propres sorties ; registre périmé ou forgé, et un fichier de l'auteur était
// remplacé sans un mot ; une mise à jour depuis la 2.5.0 demandait trois constructions refusées de suite. Le contrôle
// est fait au build seulement, avant toute écriture, et nomme toutes les collisions d'un coup ; la lecture de
// mjs.config.json (mjs ws, mjs serveur, createHarness) ne regarde plus le disque.

import assert from 'node:assert/strict'
import { mkdirSync, writeFileSync, readFileSync, existsSync, rmSync, readdirSync } from 'node:fs'
import { join } from 'node:path'
import { mjsTmp } from './helpers/tmp.js'
import { findConfig } from '../src/bundler/config.js'
import { Bundler, terminateSharedWorkerPool } from '../src/bundler/index.js'

const MARQUE  = '/* @generated by ModularJS */'
const carte   = ['<p class="c">carte</p>', '<style>', '  .c', '    color: red', '</style>', '<style name="large">', '  .c', '    color: blue', '</style>'].join('\n')
const auteur  = 'export const aide = 42 // fichier de l auteur\n'
// sorties d'une construction par la 2.5.0 : manifeste et liste de pré-cache sans marque
const manifeste250 = ["const µCore = '/modularjs/mjs_core-5f4edbfe.js';", 'const µPaths = {"carte":"carte-25b0059f.js"};', 'const µReady = import(µCore).then(async ({ µ }) => {', '  µ.paths = µPaths;', '  µ.version = "7ec786c6";', '});'].join('\n')
const precache250  = JSON.stringify({ version: '7ec786c6', assets: ['/modularjs/carte-25b0059f.js', '/modularjs/mjs_core-5f4edbfe.js'] }, null, 2) + '\n'

// projet qui construit dans ses sources (`sourceDir: "."`), sortie sous public/modularjs
function projet(prefixe: string): string {
  const root = mjsTmp(prefixe)
  mkdirSync(join(root, 'composants'), { recursive: true })
  writeFileSync(join(root, 'composants', 'carte.mjs'), carte)
  writeFileSync(join(root, 'composants', 'page.mjs'), '<mjs-carte layout="large"></mjs-carte>\n')
  return root
}

const sortie  = (root: string) => join(root, 'public', 'modularjs')
const options = (root: string, manifeste = 'public/modularjs/bundle.js') => ({ sourceDir: root, outputDir: sortie(root), manifestPath: join(root, manifeste), keepFailedComponents: false })

async function construire(opts: Record<string, unknown>): Promise<string[]> {
  const b = new Bundler(opts)
  const s = await b.compile()
  await b.close()
  return s.errors.map(e => e.message)
}

describe('sortie dans le dossier des sources : la marque des fichiers produits, seule preuve qu\'une sortie vient du build', function () {
  this.timeout(180000)

  after(async () => {
    await terminateSharedWorkerPool()
  })

  it('les sorties à nom fixe portent la marque ; hors du dossier des sources, aucune', async () => {
    const root = projet('marque-presente')
    assert.deepEqual(await construire(options(root)), [])
    assert.ok(readFileSync(join(sortie(root), 'bundle.js'), 'utf-8').startsWith(`${MARQUE}\n`), 'manifeste sans marque')
    assert.ok(readFileSync(join(sortie(root), 'carte.large.css'), 'utf-8').startsWith(`${MARQUE}\n`), 'feuille sans marque')
    assert.equal(JSON.parse(readFileSync(join(sortie(root), 'mjs-precache.json'), 'utf-8'))['@generated'], 'ModularJS')
    const ailleurs = mjsTmp('marque-absente')
    mkdirSync(join(ailleurs, 'src'), { recursive: true })
    writeFileSync(join(ailleurs, 'src', 'carte.mjs'), carte)
    writeFileSync(join(ailleurs, 'src', 'page.mjs'), '<mjs-carte layout="large"></mjs-carte>\n')
    const out = join(ailleurs, 'out')
    assert.deepEqual(await construire({ sourceDir: join(ailleurs, 'src'), outputDir: out, manifestPath: join(out, 'bundle.js'), keepFailedComponents: false }), [])
    assert.ok(!readFileSync(join(out, 'bundle.js'), 'utf-8').includes('@generated'), 'marque hors du dossier des sources')
    assert.ok(!readFileSync(join(out, 'carte.large.css'), 'utf-8').includes('@generated'), 'marque hors du dossier des sources')
    assert.ok(!readFileSync(join(out, 'mjs-precache.json'), 'utf-8').includes('@generated'), 'marque hors du dossier des sources')
  })

  it('fichier unique (`js: "bundle"`) avec carte de source : la marque décale le code d\'une ligne, la carte aussi', async () => {
    const dans = projet('marque-bundle-carte')
    const hors = mjsTmp('marque-bundle-carte-hors')
    mkdirSync(join(hors, 'src'), { recursive: true })
    writeFileSync(join(hors, 'src', 'carte.mjs'), carte)
    writeFileSync(join(hors, 'src', 'page.mjs'), '<mjs-carte layout="large"></mjs-carte>\n')
    const commun = { js: 'bundle', sourceMap: 'always', urlPrefix: '/modularjs', keepFailedComponents: false }
    assert.deepEqual(await construire({ ...options(dans), ...commun }), [])
    assert.deepEqual(await construire({ ...commun, sourceDir: join(hors, 'src'), outputDir: join(hors, 'out'), manifestPath: join(hors, 'out', 'bundle.js') }), [])
    const code = readFileSync(join(sortie(dans), 'bundle.js'), 'utf-8')
    assert.ok(code.startsWith(`${MARQUE}\n`), 'fichier unique sans marque')
    assert.equal(code.slice(MARQUE.length + 1), readFileSync(join(hors, 'out', 'bundle.js'), 'utf-8'))
    const carteDans = JSON.parse(readFileSync(join(sortie(dans), 'bundle.js.map'), 'utf-8'))
    const carteHors = JSON.parse(readFileSync(join(hors, 'out', 'bundle.js.map'), 'utf-8'))
    assert.equal(carteDans.mappings, `;${carteHors.mappings}`)
  })

  it('registre retiré (clone neuf, registre ignoré par git) : la construction suivante passe et réécrit ses sorties', async () => {
    const root = projet('marque-sans-registre')
    assert.deepEqual(await construire(options(root)), [])
    rmSync(join(sortie(root), '.mjs-outputs.json'))
    writeFileSync(join(root, 'composants', 'autre.mjs'), '<p>autre</p>\n')
    assert.deepEqual(await construire(options(root)), [])
    assert.match(readFileSync(join(sortie(root), 'bundle.js'), 'utf-8'), /autre/)
  })

  it('manifeste rangé ailleurs le temps d\'une construction, puis remis : les deux constructions passent', async () => {
    const root = projet('marque-manifeste-deplace')
    assert.deepEqual(await construire(options(root)), [])
    assert.deepEqual(await construire(options(root, 'public/preprod/bundle.js')), [])
    writeFileSync(join(root, 'composants', 'autre.mjs'), '<p>autre</p>\n')
    assert.deepEqual(await construire(options(root)), [])
    assert.match(readFileSync(join(sortie(root), 'bundle.js'), 'utf-8'), /autre/)
  })

  it('registre périmé ou forgé qui nomme le fichier de l\'auteur : refus, fichier intact', async () => {
    const root = projet('marque-registre-perime')
    const main = join(root, 'app', 'main.js')
    assert.deepEqual(await construire(options(root, 'app/main.js')), [])
    rmSync(main)
    assert.deepEqual(await construire(options(root)), [])
    writeFileSync(main, auteur)
    const perime = await construire(options(root, 'app/main.js'))
    assert.equal(readFileSync(main, 'utf-8'), auteur, 'fichier de l\'auteur remplacé (registre périmé)')
    assert.ok(perime.some(m => m.includes(main)), perime.join('\n') || 'aucune erreur')
    writeFileSync(join(root, 'app', '.mjs-outputs.json'), '{"extensions":[".js"],"manifests":["main.js"],"stable":["main.js"]}')
    const forge = await construire(options(root, 'app/main.js'))
    assert.equal(readFileSync(main, 'utf-8'), auteur, 'fichier de l\'auteur remplacé (registre forgé)')
    assert.ok(forge.some(m => m.includes(main)), forge.join('\n') || 'aucune erreur')
  })

  it('mise à jour depuis la 2.5.0 : manifeste et précache reconnus, la feuille sans marque seule refusée, puis tout passe', async () => {
    const root = projet('marque-maj-250')
    mkdirSync(sortie(root), { recursive: true })
    writeFileSync(join(sortie(root), 'bundle.js'), manifeste250)
    writeFileSync(join(sortie(root), 'mjs-precache.json'), precache250)
    writeFileSync(join(sortie(root), 'carte.large.css'), '.c{color:blue}')
    writeFileSync(join(sortie(root), '.mjs-outputs.json'), '{"extensions":[".css",".js",".map"]}')
    const erreurs = await construire(options(root))
    assert.equal(erreurs.length, 1, erreurs.join('\n') || 'aucune erreur')
    assert.ok(erreurs[0].includes(join(sortie(root), 'carte.large.css')), erreurs[0])
    assert.ok(!erreurs[0].includes(join(sortie(root), 'bundle.js')) && !erreurs[0].includes(join(sortie(root), 'mjs-precache.json')), erreurs[0])
    assert.equal(readFileSync(join(sortie(root), 'bundle.js'), 'utf-8'), manifeste250, 'manifeste réécrit par la construction refusée')
    rmSync(join(sortie(root), 'carte.large.css'))
    assert.deepEqual(await construire(options(root)), [])
    assert.ok(readFileSync(join(sortie(root), 'bundle.js'), 'utf-8').startsWith(`${MARQUE}\n`))
    assert.equal(JSON.parse(readFileSync(join(sortie(root), 'mjs-precache.json'), 'utf-8'))['@generated'], 'ModularJS')
  })

  for (const keep of [false, true]) {
    it(`${keep ? 'développement' : 'build'} : trois fichiers de l'auteur aux noms des sorties, un seul refus les nomme tous, rien n'est écrit`, async () => {
      const root = projet(`marque-trois-collisions-${keep}`)
      mkdirSync(sortie(root), { recursive: true })
      writeFileSync(join(sortie(root), 'bundle.js'), auteur)
      writeFileSync(join(sortie(root), 'mjs-precache.json'), '{ "auteur": true }\n')
      writeFileSync(join(sortie(root), 'carte.large.css'), '/* feuille de l auteur */\n.c { font-size: 2em }\n')
      const avant = readdirSync(sortie(root)).sort()
      const erreurs = await construire({ ...options(root), keepFailedComponents: keep })
      assert.equal(erreurs.length, 1, erreurs.join('\n') || 'aucune erreur')
      for (const f of ['bundle.js', 'mjs-precache.json', 'carte.large.css']) assert.ok(erreurs[0].includes(join(sortie(root), f)), `${f} absent du refus : ${erreurs[0]}`)
      assert.deepEqual(readdirSync(sortie(root)).sort(), avant, 'fichiers écrits par la construction refusée')
      assert.equal(readFileSync(join(sortie(root), 'bundle.js'), 'utf-8'), auteur)
    })
  }

  it('lecture de mjs.config.json : aucun refus tiré du disque (mjs ws, mjs serveur, createHarness démarrent)', () => {
    const root = projet('marque-lecture-config')
    mkdirSync(join(root, 'public', 'modularjs'), { recursive: true })
    mkdirSync(join(root, 'src'), { recursive: true })
    writeFileSync(join(root, 'public', 'modularjs', 'bundle.js'), "const µCore = '/modularjs/mjs_core-aaaaa.js'; // manifeste déployé sans registre\n")
    writeFileSync(join(root, 'src', 'main.js'), auteur)
    writeFileSync(join(root, 'mjs.config.json'), JSON.stringify({ sourceDir: '.', outputDir: 'public/modularjs', manifestPath: 'public/modularjs/bundle.js' }))
    assert.doesNotThrow(() => findConfig(root))
    writeFileSync(join(root, 'mjs.config.json'), JSON.stringify({ sourceDir: '.', outputDir: 'public/modularjs', manifestPath: 'src/main.js' }))
    assert.doesNotThrow(() => findConfig(root))
    assert.ok(existsSync(join(root, 'src', 'main.js')))
  })
})
